  if(!year||!month||!day||!Number.isInteger(amount)||amount<1)return '';
  if(unit==='days'||unit==='weeks'){const date=new Date(Date.UTC(year,month-1,day));date.setUTCDate(date.getUTCDate()+amount*(unit==='weeks'?7:1));return date.toISOString().slice(0,10)}
  const monthOffset=unit==='years'?amount*12:amount,targetIndex=year*12+(month-1)+monthOffset,targetYear=Math.floor(targetIndex/12),targetMonth=targetIndex%12,lastDay=new Date(Date.UTC(targetYear,targetMonth+1,0)).getUTCDate();
  return `${String(targetYear).padStart(4,'0')}-${String(targetMonth+1).padStart(2,'0')}-${String(Math.min(day,lastDay)).padStart(2,'0')}`;
